CREATE TABLE "HealthPatientCondition" (id TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,kind TEXT NOT NULL,label TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3),narrative TEXT NOT NULL,"medicalRecordId" TEXT,"professionalId" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthPatientCondition_patientId_kind_endedAt_idx" ON "HealthPatientCondition"("patientId",kind,"endedAt");
CREATE TABLE "HealthOngoingMedication" (id TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"medicineId" TEXT,name TEXT NOT NULL,dosage TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3),"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthOngoingMedication_patientId_endedAt_idx" ON "HealthOngoingMedication"("patientId","endedAt");
CREATE TABLE "HealthClinicalQuestionnaire" (id TEXT PRIMARY KEY,code TEXT NOT NULL,version INTEGER NOT NULL,name TEXT NOT NULL,"specialtyId" TEXT,"conditionKind" TEXT,required BOOLEAN NOT NULL DEFAULT false,fields JSONB NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(code,version));
CREATE TABLE "HealthClinicalQuestionnaireResponse" (id TEXT PRIMARY KEY,"questionnaireId" TEXT NOT NULL REFERENCES "HealthClinicalQuestionnaire"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,answers JSONB NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("questionnaireId","medicalRecordId"));
CREATE TABLE "HealthMedicationAdministration" (id TEXT PRIMARY KEY,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"medicineId" TEXT,"medicineName" TEXT NOT NULL,dosage TEXT NOT NULL,quantity DOUBLE PRECISION NOT NULL,"administeredAt" TIMESTAMP(3) NOT NULL,"patientOwned" BOOLEAN NOT NULL,"professionalId" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"movementId" TEXT UNIQUE,materials JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthCareRevision" (id TEXT PRIMARY KEY,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,reason TEXT NOT NULL,before JSONB NOT NULL,after JSONB NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthCareRevision_medicalRecordId_createdAt_idx" ON "HealthCareRevision"("medicalRecordId","createdAt");
CREATE TABLE "HealthClinicalExamReview" (id TEXT PRIMARY KEY,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"examRequestId" TEXT NOT NULL,"performedAt" TIMESTAMP(3),"resultedAt" TIMESTAMP(3),"resultChanged" BOOLEAN NOT NULL,"providerSupplierId" TEXT,evaluation TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthCounterreference" (id TEXT PRIMARY KEY,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"referralId" TEXT NOT NULL,response TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthInternalCareReferral" (id TEXT PRIMARY KEY,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"appointmentId" TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthSpecialtyProcedureRule" (id TEXT PRIMARY KEY,"unitId" TEXT,"specialtyId" TEXT,"eventType" TEXT NOT NULL,"procedureId" TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 1,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthPrescriptionTemplate" (id TEXT PRIMARY KEY,name TEXT NOT NULL,"prescriptionType" TEXT NOT NULL,items JSONB NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthClinicalDocumentTemplate" (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,kind TEXT NOT NULL,"bodyHtml" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthClinicalDocumentOrder" (id TEXT PRIMARY KEY,"medicalRecordId" TEXT NOT NULL REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,kind TEXT NOT NULL,"templateId" TEXT,data JSONB NOT NULL,"documentId" TEXT UNIQUE,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "HealthPrescription" ADD COLUMN "prescriptionType" TEXT NOT NULL DEFAULT 'SIMPLE',ADD COLUMN "manualGroup" TEXT,ADD COLUMN barcode TEXT UNIQUE;
ALTER TABLE "HealthPrescriptionItem" ADD COLUMN "usageType" TEXT NOT NULL DEFAULT 'ACUTE',ADD COLUMN "treatmentDays" INTEGER;
